sp_widget.client_script:
api.controller = function($scope, $rootScope) {
	var c = this;
	$rootScope.$on('CaseId', function(event, sysId) {
		$scope.arr = [];
	})
	$rootScope.$on('AuditSysId', function(event, sysId) {
		var sys = sysId;
		c.server.get({'action': 'fetch', 'value': sys})
			.then(function(res) {
			$scope.receivedSysId = true;
			$scope.arr = res.data.arr;
		})

	});
};

sp_widget.css:
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #f4f4f4;
}

.header {
   font-family: "Arial", sans-serif;
    font-size: 2.4rem;
    font-weight: bold;
    color: #03428E;
    background-color: #f9f9f9;
    padding: 2rem;
    border-radius: 1rem;
    box-shadow: 0 .4rem .8rem rgba(0, 0, 0, .1);
    display: flex;
    align-items: center;
    justify-content: space-between;
    transition: background-color .3s ;
    margin-bottom: 2rem;
}

.case-sheet {
    max-width: 100%;
    margin: 10px auto; /* Reduced margin to bring case sheet closer to header */
    background-color: white;
    border: 1px solid #ccc;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
    overflow: hidden;
}

.section {
    padding: 10px;
    border-bottom: 1px solid #eee;
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

.section:last-child {
    border-bottom: none;
}

.section-title {
    font-weight: bold;
    margin-bottom: 5px;
    color: #444;
    font-size: 16px;
    flex: 1;
}

span.section-title {
  margin-left: 14px;

}  

.section-content {
    flex: 1;
    margin-left: 10px;
    line-height: 1.5;
    color: #333;
}

.row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 10px;
  	margin-right: 20px;
  	font-size:110%;
}

.label {
    display: inline;
    padding: .2em .6em .3em;
    font-size: 110%;
    font-weight: bold;
    line-height: 1;
    color: black;
    text-align: center;
    white-space: nowrap;
    vertical-align: baseline;
    border-radius: .25em;
}

.value {
    color: #111;
}

.remarks {
    color: #222;
    margin-top: 10px;
}

sp_widget.script:
(function() {


	if(input && input.action == 'fetch'){


		data.arr = [];
		var gr = new GlideRecord('x_rptp_kotak_underwriter_decision'); // Fixed typo in 'GlideRecord'
		gr.addQuery('case_id', input.value);
		gr.query();
		while (gr.next()) { // Removed unnecessary semicolon
			var obj = {
				decision: gr.getValue('decision'),
				comments: gr.getValue('comments'),
				remarks: gr.getValue('remarks'),
				user: gr.getValue('sys_created_by'),
				date: gr.getValue('sys_created_on') // Fixed typo in 'getValue'
			};
			data.arr.push(obj);
		}
	}
	//gs.addErrorMessage(JSON.stringify(data.arr)); // Moved outside of loop to avoid multiple messages
})();
